# Name, file, one-line directory description, section group, lead, focused capabilities, workflow, connected pages, screenshot.
sections=[
 dict(name='Incident Command',file='command.html',group='Command & coordination',short='A command view of incident priorities, organization, and decisions.',lead='Keep the incident’s priorities and current condition visible to the people directing the response. The command workspace draws together operational health, open issues, and the information needed for the next decision.',features=[('Incident overview','See incident details, operational objectives, active teams, current tasks, alerts, and key conditions without opening each record separately.'),('Command structure','See the branches, divisions, groups, and staff positions carrying out the incident organization.'),('Decision support','Use the current resource picture, intelligence, weather, and safety information to guide priorities.'),('Continuity','Keep significant updates and command activity in the incident record so the next operational period has context.')],workflow=[('Set direction','Define priorities and objectives for the period.'),('Watch the picture','Review teams, assignments, hazards, and notable changes in one view.'),('Act on changes','Pass decisions into operations, planning, and the supporting sections.')],connections=[('operations.html','Operations'),('situational-awareness.html','Situational awareness'),('planning.html','Planning')],shot='Incident Command dashboard with health indicators and current priorities'),
 dict(name='Operations',file='operations.html',group='Command & coordination',short='Team assignments, task progress, and operational organization.',lead='Move assignments from briefing to completion while keeping team availability and task progress clear. Operations connects supervisors, teams, and field updates in the same incident record.',features=[('Organization','Set up branches, divisions, and groups that match the incident’s actual span of control.'),('Team detail','Keep team type, personnel, vehicles, aircraft, equipment, and activity logs together.'),('Task board','Follow planned, assigned, active, and completed tasks with their responsible teams and map context.'),('Status board','Track team availability, assignment, movement, arrival, rest, and out-of-service conditions.')],workflow=[('Organize','Place teams under the right supervisor and define the work.'),('Assign','Brief and dispatch teams with task details and map context.'),('Track','Use status and field reports to update the operational picture.')],connections=[('field.html','Field app'),('mapping.html','Mapping'),('logistics.html','Logistics')],shot='Operations board with teams, supervisors, and tasks'),
 dict(name='Planning',file='planning.html',group='Command & coordination',short='Objectives, strategies, operational periods, and planning-cycle work.',lead='Turn information into a plan people can execute. Planning maintains incident objectives, strategies, assignments, and the work that connects one operational period to the next.',features=[('Planning cycle','Use meetings and Planning P checklists to organize the work leading to an incident action plan.'),('Objectives and strategies','Keep objectives tied to tactics, resources, and the conditions that may change them.'),('Assignment development','Build search and operational assignments with map references, hazards, and supervisor context.'),('Search planning','Use probability of area and detection methods alongside segments and search results when managing SAR work.')],workflow=[('Gather','Pull in situation, resource, weather, safety, and intelligence updates.'),('Develop','Set objectives, compare strategies, and prepare assignments.'),('Brief and revise','Issue the plan, follow execution, and carry changes into the next period.')],connections=[('sar-tools.html','SAR tools'),('mapping.html','Mapping'),('documentation.html','Documentation')],shot='Planning workspace with objectives, strategies, and period checklist'),
 dict(name='Situational Awareness',file='situational-awareness.html',group='Command & coordination',short='A common operating picture from live status, maps, and field reports.',lead='Build a coherent view from many moving parts. Situational awareness brings the incident map, team and task status, hazards, weather, and field information into the same decision space.',features=[('Common picture','Use the dashboard to see active work and changes requiring command attention.'),('Map context','Relate resources, assignments, clues, hazards, and access to their locations.'),('Operational updates','Follow status changes and narrative entries as work unfolds.'),('Situation products','Carry the current picture into briefings and situation reporting.')],workflow=[('Collect','Receive updates from field teams and staff workspaces.'),('Connect','Relate them to locations, assignments, resources, and priorities.'),('Communicate','Use the shared picture for briefings, decisions, and reports.')],connections=[('command.html','Incident Command'),('mapping.html','Mapping'),('reporting.html','Situation reporting')],shot='Command projection board with map, teams, tasks, and alerts'),
 dict(name='Mapping & GIS',file='mapping.html',group='Search & geography',short='Operational geometry, map layers, and geographic exchange.',lead='Make the map an operational workspace. ArcHorizon connects geographic features to assignments, hazards, clues, facilities, and planning records.',features=[('Drawing tools','Create points, lines, polylines, polygons, rectangles, arcs, circles, rings, and buffers.'),('Operational meaning','Convert geometry into assignments, planning segments, hazards, and clues; edit features from the map.'),('Reference layers','Work with default layers and attach supported ArcGIS REST datasets, including public mapping sources.'),('Exchange','Move operational geography between systems with GeoJSON.')],workflow=[('Locate','Find a coordinate, address, place, or existing incident feature.'),('Describe','Draw or generate the geometry needed for the plan.'),('Use','Attach the feature to an assignment or record and share its context.')],connections=[('sar-tools.html','SAR tools'),('operations.html','Operations'),('intelligence.html','Intelligence & information')],shot='GIS window with operational layers and drawing tools'),
 dict(name='SAR Tools',file='sar-tools.html',group='Search & geography',short='Search areas, patterns, probability planning, and SAR-specific tools.',lead='Support search decisions with tools built for the work of finding people and aircraft. The SAR toolkit connects search theory, geography, and field assignments.',features=[('Search design','Create grids, planning segments, and patterns such as expanding square and creeping line.'),('Probability planning','Work with POA and POD methods, including Mattson, O’Connor, proportional, combined, trail-based, and statistical approaches.'),('Aircraft search','Use altitude and terrain context for airborne beacon line-of-sight planning rings.'),('Distress information','Capture structured aircraft distress beacon reports, including first and last signal details.')],workflow=[('Estimate','Define the last known information and candidate search areas.'),('Plan','Compare search priorities and generate map-based work.'),('Learn','Bring search results and new clues back into the next allocation decision.')],connections=[('mapping.html','Mapping & GIS'),('intelligence.html','Intelligence & information'),('planning.html','Planning')],shot='SAR planning map with segments, probability values, and search patterns'),
 dict(name='Intelligence & Information',file='intelligence.html',group='Information & public affairs',short='Subjects, clues, observations, leads, and the intel record.',lead='Keep incoming information traceable from first report to operational action. Intelligence records connect people, findings, leads, and observations with the work they inform.',features=[('Subjects','Maintain missing-person, witness, reporting-party, vehicle, and aircraft records.'),('Clues','Record clues with location, context, and follow-up rather than burying them in general notes.'),('Intel items','Add observations to an evolving information item as details are confirmed or revised.'),('Leads and log','Track source, summary, priority, assignee, status, and intelligence activity.')],workflow=[('Capture','Record the source and content of a new report.'),('Evaluate','Connect it to subjects, locations, and existing information.'),('Task','Assign follow-up or turn a finding into map and operational work.')],connections=[('mapping.html','Mapping & GIS'),('operations.html','Operations'),('public-affairs.html','Public affairs')],shot='Intel window with subjects, clues, and lead list'),
 dict(name='Public Affairs',file='public-affairs.html',group='Information & public affairs',short='Public messaging, press releases, and misinformation tracking.',lead='Give the public information function an accountable workspace. Prepare releases, record what has been shared, and watch for claims that need correction.',features=[('Release editor','Draft public statements and press releases with the incident’s current facts.'),('Letterhead','Apply the organization’s release format for a consistent outward-facing document.'),('Misinformation tracker','Record a questionable claim, where it appeared, and the response or correction.'),('Coordination','Link public messaging to command approval and the current situation picture.')],workflow=[('Verify','Check the information against incident records and command direction.'),('Publish','Prepare and issue an approved statement.'),('Monitor','Track public reaction and correct consequential misinformation.')],connections=[('command.html','Incident Command'),('situational-awareness.html','Situational awareness'),('liaison.html','Liaison')],shot='PIO workspace with release draft and misinformation tracker'),
 dict(name='Liaison',file='liaison.html',group='Information & public affairs',short='Agency status, contacts, coordination, and partner feedback.',lead='Keep partner agencies in the incident picture. Liaison records who is involved, what each agency needs, and the coordination that produces action.',features=[('Agency board','See participating agencies, their current status, contacts, and involvement.'),('Contact log','Record conversations, commitments, and follow-up with a clear time and source.'),('Feedback to action','Turn partner feedback into tasks or strategies when it changes the plan.'),('Planning connection','Keep interagency meetings and coordination aligned with the planning cycle.')],workflow=[('Connect','Identify the partner and record the point of contact.'),('Coordinate','Log requests, constraints, and commitments.'),('Follow through','Route actionable items to planning or operations and track the outcome.')],connections=[('planning.html','Planning'),('logistics.html','Logistics'),('public-affairs.html','Public affairs')],shot='Liaison agency board with statuses and contact log'),
 dict(name='Safety & Medical Support',file='medical-safety.html',group='Support & safety',short='Hazards, operational risk, release checks, and medical support context.',lead='Bring safety considerations into assignments before a team leaves and as conditions change. The workspace connects hazards, weather triggers, risk assessment, and release decisions.',features=[('Hazard picture','Map and document hazards so supervisors and teams can see what affects their assignment.'),('Risk assessment','Use an operational risk matrix to weigh conditions and mitigation before release.'),('Release checks','Verify paperwork, team tracking, and relevant weather and safety triggers before ground resources deploy.'),('Medical context','Keep aid, medical resources, and field safety updates visible in incident support and reporting.')],workflow=[('Identify','Document hazards and medical or environmental concerns.'),('Mitigate','Record controls and check the team’s readiness to deploy.'),('Monitor','Review changing conditions and pass safety updates to assigned teams.')],connections=[('weather.html','Weather'),('operations.html','Operations'),('field.html','Field app')],shot='Safety workspace showing hazard map and release checklist'),
 dict(name='Weather',file='weather.html',group='Support & safety',short='Incident forecasts, aviation conditions, and alert monitoring.',lead='Bring weather into planning and safety decisions. The weather workspace presents the incident location’s conditions alongside forecast and aviation information.',features=[('Incident summary','Review current conditions, a three-day outlook, and active alerts for the incident area.'),('Aviation weather','Read METAR and TAF information for flight operations.'),('NWS alerts','See National Weather Service warnings and advisories relevant to the operation.'),('Location control','Use the ICP location or an override when planning for another area.')],workflow=[('Review','Check current and forecast conditions for the operating area.'),('Apply','Connect a weather concern to assignment timing, aviation work, or a safety trigger.'),('Update','Refresh information when connectivity is available and conditions change.')],connections=[('medical-safety.html','Safety & medical support'),('planning.html','Planning'),('situational-awareness.html','Situational awareness')],shot='Weather window with incident summary, aviation, and alerts'),
 dict(name='Logistics',file='logistics.html',group='Support & safety',short='Resource requests, equipment support, and accountability.',lead='Move needs into fulfilled support. Logistics tracks requests, resources, and the handoffs that keep teams equipped and available.',features=[('Request management','Log a resource need, follow its status, and connect it to the team or assignment that needs it.'),('Resource picture','See available and assigned equipment, vehicles, and supporting resources.'),('Support handoff','Record where equipment comes from and where it returns after use.'),('Check-in and demobilization','Keep arrival, assignment, and release of resources organized.')],workflow=[('Request','Capture what is needed, who asked, and when it is needed.'),('Source','Track procurement or allocation and communicate the response.'),('Account','Confirm issue, return, and closeout.')],connections=[('operations.html','Operations'),('finance.html','Finance'),('documentation.html','Documentation')],shot='Logistics resource request dashboard and request list'),
 dict(name='Communications',file='communications.html',group='Support & safety',short='Channel plans, radio resources, and field communications.',lead='Keep communications planning close to operational organization. Record the channels, equipment, and coordination needed to link command, supervisors, and field teams.',features=[('Channel plan','Document assignments and purposes for command, operations, and tactical channels.'),('Incident communications plan','Build the communications information teams need in their briefing and incident forms.'),('Radio resources','Track available communications equipment and the support needed to deploy it.'),('Interoperability','Record coordination with other agencies and the methods used to reach them.')],workflow=[('Plan','Match channels and contact paths to the organization and terrain.'),('Brief','Give teams the current communications plan.'),('Adjust','Record changes and get them to affected users promptly.')],connections=[('operations.html','Operations'),('logistics.html','Logistics'),('field.html','Field app')],shot='Communications plan with channel assignments and resource list'),
 dict(name='Finance',file='finance.html',group='Support & safety',short='Cost forecasts and resource consumption planning.',lead='Give incident leadership a practical view of expected resource costs. Finance draws on resource use and fuel assumptions to support planning conversations.',features=[('Cost forecast','Estimate how resource decisions affect the incident’s expected cost.'),('Fuel profiles','Use a consistent set of gas, diesel, Jet-A, and 100LL assumptions with local averages.'),('Resource context','Relate cost inputs to vehicles, aircraft, equipment, and staffing.'),('Planning handoff','Share forecast context with command and logistics as the operation changes.')],workflow=[('Set assumptions','Enter current local rates and resource profiles.'),('Estimate','Review the projected cost of the operational plan.'),('Revise','Update the forecast when resources or expected duration change.')],connections=[('logistics.html','Logistics'),('planning.html','Planning'),('command.html','Incident Command')],shot='Finance forecast with resource and fuel assumptions'),
 dict(name='Documentation & Forms',file='documentation.html',group='Records & field',short='Incident logs, standardized forms, and record reuse.',lead='Preserve the incident record without making staff re-enter the same facts. Documentation connects activity logs and incident fields with forms and exports.',features=[('Narrative and activity logs','Keep task, team, status, and unit entries in a traceable record, including ICS-214-style activity.'),('Forms registry','Use profiles such as ICS or Canadian ICS with a per-form mapping of incident fields.'),('Interview and SAR forms','Support structured records such as aircraft reporting-party and CAPF 106 interview forms.'),('Data reuse','Populate mapped form fields from information already held in the incident workspace.')],workflow=[('Record','Capture the activity or report at the point where it happens.'),('Review','Check the entry and supporting incident data.'),('Produce','Generate the appropriate form or export for the audience.')],connections=[('reporting.html','Situation reporting'),('planning.html','Planning'),('intelligence.html','Intelligence & information')],shot='Forms registry and incident activity log'),
 dict(name='Situation Reporting',file='reporting.html',group='Records & field',short='SITREP, ICS-209, and briefings from the current incident picture.',lead='Turn the current operational picture into a clear situation report. Reporting draws from command, operations, safety, weather, and resources to describe what changed and what comes next.',features=[('SITREP workspace','Assemble current conditions, actions, issues, and anticipated needs.'),('Operational status','Use task and team progress to keep the report aligned with work in the field.'),('ICS-209 export','Carry situation data into the ICS-209 format.'),('Other report formats','Use the same incident information for other situation-report outputs.')],workflow=[('Collect','Bring together the latest field and staff inputs.'),('Synthesize','Summarize the situation and identify needs or decisions.'),('Distribute','Produce the report and retain it with the incident record.')],connections=[('situational-awareness.html','Situational awareness'),('documentation.html','Documentation & forms'),('command.html','Incident Command')],shot='Situation report editor with ICS-209 export'),
 dict(name='Companion Field App',file='field.html',group='Records & field',short='Assignments, maps, status, and field reporting on mobile.',lead='Give field personnel a focused view of the work assigned to them. The companion app connects the team’s task, map, status, and observations with the command workspace.',features=[('Assignment home','Show the team’s current task, location, and key details in a focused view.'),('Map and task detail','Put geographic context and assignment information in reach during field work.'),('Status and check-in','Send movement and progress updates without navigating the full desktop application.'),('Field reports','Capture narrative entries, hazards, intel, and messages from the team.')],workflow=[('Receive','Review the assignment and map before departing.'),('Report','Update status and record observations as work progresses.'),('Close','Return results and noteworthy information to the incident record.')],connections=[('operations.html','Operations'),('mapping.html','Mapping & GIS'),('intelligence.html','Intelligence & information')],shot='Mobile assignment home with task, narrative, and status controls',kind='Mobile companion app')]
# Separate architecture page already exists.
group_order=['Command & coordination','Search & geography','Information & public affairs','Support & safety','Records & field']

def head(title,description):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#0b2740"><meta name="description" content="{escape(description,quote=True)}"><title>{escape(title)} | ArcHorizon</title><link rel="icon" type="image/png" href="archorizon-app-icon.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Exo+2:wght@600;700;800&family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="styles.css"><script src="theme.js" defer></script></head><body>'''
def header(current):
 items=[('index.html','Overview'),('features.html','Features'),('command.html','Command'),('operations.html','Operations'),('planning.html','Planning'),('field.html','Field app'),('offline.html','Offline'),('open-source.html','Open source')]
 links=''.join(f'<a href="{f}"'+(' aria-current="page"' if current==f else '')+f'>{label}</a>' for f,label in items)
 return f'''<header class="site-header"><div class="wrap header-inner"><a class="brand" href="index.html" aria-label="ArcHorizon home"><img src="archorizon-logo-dark.png" width="307" height="107" alt="ArcHorizon — Incident Command Assistant"></a><nav class="site-nav" aria-label="Main navigation">{links}</nav><button class="theme-toggle" type="button" aria-label="Toggle dark mode" aria-pressed="false">☾ Dark mode</button></div></header>'''
def footer():
 groups=[('Explore',[('index.html','Overview'),('features.html','All features'),('offline.html','Offline operation'),('open-source.html','Open source')]),('Command & information',[('command.html','Incident Command'),('operations.html','Operations'),('planning.html','Planning'),('situational-awareness.html','Situational awareness'),('intelligence.html','Intelligence'),('public-affairs.html','Public affairs'),('liaison.html','Liaison')]),('Support & records',[('medical-safety.html','Safety & medical support'),('weather.html','Weather'),('logistics.html','Logistics'),('communications.html','Communications'),('finance.html','Finance'),('documentation.html','Documentation'),('reporting.html','Situation reporting')]),('Search & field',[('mapping.html','Mapping & GIS'),('sar-tools.html','SAR tools'),('field.html','Field app')])]
 columns=''.join('<nav class="footer-links" aria-label="Footer '+title+'"><h2>'+title+'</h2><ul>'+''.join(f'<li><a href="{href}">{label}</a></li>' for href,label in items)+'</ul></nav>' for title,items in groups)
 return f'''<footer><div class="wrap"><div class="footer-main"><div class="footer-about"><a href="index.html" aria-label="ArcHorizon home"><img src="archorizon-logo-dark.png" width="307" height="107" alt="ArcHorizon — Incident Command Assistant"></a><p>Plan, Coordinate, Respond — Together.</p><a class="footer-contact" href="{ACS}">Contact Arcadia Command Solutions ↗</a></div>{columns}</div><div class="footer-developer"><img src="arcadia-command-solutions-logo.png" width="600" height="465" alt="Arcadia Command Solutions logo"><div><span class="developer-label">Software developed by</span><strong>Arcadia Command Solutions</strong><p>Field communications and incident management consulting · South Central Michigan</p></div></div><div class="footer-bottom"><p>© 2026 Arcadia Command Solutions. ArcHorizon · Incident Command Assistant.</p><a href="#top">Back to top ↑</a></div></div></footer>'''
def screenshot(label,kind='Desktop application'):
 return f'''<figure class="screenshot-slot"><div class="screenshot-stage"><span class="screenshot-icon" aria-hidden="true">▧</span><strong>Application screenshot</strong><span>{escape(label)}</span></div><figcaption>{escape(kind)} · Replace with your ArcHorizon screenshot</figcaption></figure>'''
def page(d):
 features=''.join(f'<article class="module-feature"><h3>{escape(a)}</h3><p>{escape(b)}</p></article>' for a,b in d['features'])
 flow=''.join(f'<li><strong>{escape(a)}</strong><span>{escape(b)}</span></li>' for a,b in d['workflow'])
 related=''.join(f'<a href="{f}">{escape(label)} →</a>' for f,label in d['connections'])
 name=escape(d['name'])
 return head(d['name'],d['short'])+'<div id="top">'+header(d['file'])+f'''<main><section class="page-hero"><div class="wrap"><div class="breadcrumb"><a href="index.html">Overview</a> / <a href="features.html">Features</a> / {name}</div><span class="eyebrow">{escape(d['group'])}</span><h1>{name}</h1><p>{escape(d['lead'])}</p></div></section><section class="section alt"><div class="wrap"><div class="section-head"><span class="eyebrow">In this workspace</span><h2>What the section handles.</h2></div><div class="module-grid">{features}</div></div></section><section class="section"><div class="wrap split"><div><span class="eyebrow">In practice</span><h2>From input to action.</h2><p class="lead">The workspace shares its records with related areas of the incident, so an update can inform the next task or decision.</p></div><ol class="rule-list module-flow">{flow}</ol></div></section><section class="section screenshot-section"><div class="wrap"><span class="eyebrow">Inside ArcHorizon</span><h2>See the workspace.</h2>{screenshot(d['shot'],d.get('kind','Desktop application'))}</div></section><section class="section dark"><div class="wrap"><span class="eyebrow">Connected sections</span><h2>Follow the work across ArcHorizon.</h2><div class="related">{related}<a href="features.html">All features →</a></div></div></section></main>'''+footer()+'</div></body></html>'
for d in sections:
 if d['file'] not in {'command.html','operations.html','planning.html','situational-awareness.html','field.html','medical-safety.html'}:
  (P/d['file']).write_text(page(d))
# Build a directory with direct links to every section rather than broad cards pointing to shared pages.
directory=''.join('<section class="feature-group"><h2>'+group+'</h2><ul>'+''.join(f'<li><strong><a href="{d["file"]}">{escape(d["name"])}</a></strong><span>{escape(d["short"])}</span></li>' for d in sections if d['group']==group)+'</ul></section>' for group in group_order)
feature_page=head('Features','Explore every ArcHorizon section, including command, operations, planning, intelligence, public affairs, safety, logistics, documentation, search, and field work.')+'<div id="top">'+header('features.html')+f'''<main><section class="page-hero"><div class="wrap"><div class="breadcrumb"><a href="index.html">Overview</a> / Features</div><span class="eyebrow">Program sections</span><h1>One incident. Connected workspaces.</h1><p>Explore each section of ArcHorizon, from command decisions and search planning to field reporting and the incident record.</p></div></section><section class="section"><div class="wrap feature-directory">{directory}</div></section><section class="section screenshot-section"><div class="wrap"><span class="eyebrow">Inside ArcHorizon</span><h2>See the whole workspace.</h2>{screenshot('Incident dashboard with access to each program section')}</div></section><section class="section dark"><div class="wrap"><span class="eyebrow">Architecture</span><h2>Work continues offline.</h2><p class="lead">The client retains incident data locally and uses available LAN and cloud paths for shared information.</p><a class="text-link" href="offline.html">Explore offline operation →</a></div></section></main>'''+footer()+'</div></body></html>'
# features.html is maintained with the Operations tools directory in build_operations_tools.py.
# (P/'features.html').write_text(feature_page)
# Keep the existing overview and offline explanations, while applying the shared navigation/footer.
for filename in ('offline.html',):
 f=P/filename;s=f.read_text()
 s=re.sub(r'<header class="site-header">.*?</header>',header(filename),s,count=1,flags=re.S)
 s=re.sub(r'<footer>.*?</footer>',footer(),s,count=1,flags=re.S)
 if filename=='index.html':
  s=s.replace('<a class="button" href="#capabilities">Explore capabilities</a>','<a class="button" href="features.html">Explore all features</a>')
  s=s.replace('<a class="button secondary" href="features.html">All features</a>','<a class="button secondary" href="field.html">See the field app</a>')
  s=s.replace('<p class="lead">Start with the work you need to manage, then follow the information through the rest of the operation.</p>','<p class="lead">Each major section has its own page. Browse the full directory to find the work you need.</p><p><a class="text-link" href="features.html">See every section →</a></p>')
 else:
  s=s.replace('<a class="text-link" href="features.html">Explore all features →</a>','<a class="text-link" href="features.html">Explore all features →</a>')
 f.write_text(s)
# New page styles are additive to the established ArcHorizon brand.
css='''\n.module-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:17px}.module-feature{padding:27px 29px;border:1px solid var(--line);border-left:3px solid var(--orange);background:#fff}.module-feature p{color:var(--muted);margin:0}.module-flow{counter-reset:step}.module-flow li{list-style:none;position:relative;padding-left:44px}.module-flow li:before{counter-increment:step;content:counter(step,decimal-leading-zero);position:absolute;left:0;top:18px;color:#ab5908;font-weight:800;font-size:.84rem}.footer-main{grid-template-columns:1.3fr repeat(4,minmax(0,1fr));gap:28px}.footer-contact{display:inline-block;margin-top:17px}.site-nav{gap:8px 18px}.site-nav a{white-space:nowrap}body[data-theme="dark"] .module-feature{background:#173a52;border-color:#3e6076}body[data-theme="dark"] .module-flow li:before{color:#ffad61}@media(max-width:1100px){.footer-main{grid-template-columns:repeat(3,minmax(0,1fr))}.footer-about{grid-column:1/-1}}@media(max-width:640px){.module-grid{grid-template-columns:1fr}.module-feature{padding:22px}.footer-main{grid-template-columns:repeat(2,minmax(0,1fr));gap:28px 18px}.footer-about{grid-column:1/-1}.site-nav{gap:0 14px}}\n'''
if '.module-grid{display:grid' not in (P/'styles.css').read_text():
 with (P/'styles.css').open('a') as out:out.write(css)
